package io.github.describeadmin.codegen.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;
import org.junit.jupiter.api.Test;

class FieldTypeMutaGate1Test {

    @Test
    void allKeysReturnsKeysOfAllTypesInDeclarationOrder() {
        List<String> expected = List.of(
                "string", "text", "int", "long", "decimal", "flag", "date", "datetime");
        assertEquals(expected, FieldType.allKeys());
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;

class FieldTypeMutaGate2Test {

    @Test
    void javaSimpleTypeHandlesDotAtIndexZero() throws Exception {
        // Normal cases: no dot (index -1) and a fully qualified name
        assertEquals("String", FieldType.TEXT.javaSimpleType());
        assertEquals("BigDecimal", FieldType.DECIMAL.javaSimpleType());

        // Boundary case: a dot at index 0 must still be stripped.
        // The enum constants never hit this, so set the field via reflection temporarily.
        Field f = FieldType.class.getDeclaredField("javaType");
        f.setAccessible(true);
        String original = (String) f.get(FieldType.STRING);
        try {
            f.set(FieldType.STRING, ".Foo");
            assertEquals("Foo", FieldType.STRING.javaSimpleType());
        } finally {
            f.set(FieldType.STRING, original);
        }
        assertEquals("String", FieldType.STRING.javaSimpleType());
    }
}

package io.github.describeadmin.codegen.model;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;
import org.junit.jupiter.api.Test;

class FieldTypeMutaGate3Test {

    @Test
    void keyReturnsYamlIdentifierForEveryType() {
        assertEquals("string", FieldType.STRING.key());
        assertEquals("text", FieldType.TEXT.key());
        assertEquals("int", FieldType.INT.key());
        assertEquals("long", FieldType.LONG.key());
        assertEquals("decimal", FieldType.DECIMAL.key());
        assertEquals("flag", FieldType.FLAG.key());
        assertEquals("date", FieldType.DATE.key());
        assertEquals("datetime", FieldType.DATETIME.key());
        assertEquals(
                List.of("string", "text", "int", "long", "decimal", "flag", "date", "datetime"),
                FieldType.allKeys());
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class FieldTypeMutaGate4Test {

    @Test
    void needsLengthIsTrueOnlyForString() {
        for (FieldType type : FieldType.values()) {
            if (type == FieldType.STRING) {
                assertTrue(type.needsLength(), "STRING should need length");
            } else {
                assertFalse(type.needsLength(), type + " should not need length");
            }
        }
    }
}

package io.github.describeadmin.codegen.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class FieldTypeMutaGate5Test {

    @Test
    void needsPrecisionOnlyForDecimal() {
        for (FieldType type : FieldType.values()) {
            assertEquals(type == FieldType.DECIMAL, type.needsPrecision(),
                    "needsPrecision mismatch for " + type);
        }
    }
}

